#include "PatternTools.h"
#include "ControlEdits.h"
static void testPatternSelection(const File& root,Assets& assets){
    auto source=emptyProject();source.songMode=true;source.bpm=120;source.loop=false;source.patterns[0].name="Selected phrase";source.patterns[0].colour=8;source.patterns[0].lanes[7]={{4,1,60,.8f,.25f,3},{2,.5,64,.5f,.75f,2},{1.25,10,67,.7f,1,1},{4,1,60,.8f,.25f,3}};source.patterns[0].lanes[0]={{0,.25,36,.8f}};
    Pattern incoming;incoming.name="Incoming";incoming.length=4;incoming.lanes.resize(source.tracks.size());incoming.lanes[7]={{0,.5,72,.6f}};source.patterns.push_back(incoming);source.clips={{7,0,0,8},{7,0,8,8},{0,0,0,8}};
    source.markers={{"phrase","Phrase",0,16,3}};auto original=JSON::toString(projectToJson(source));Project out;PatternEditStats stats;
    expect(extractPatternNotes(source,0,7,{0,2},false,false,out,&stats).wasOk()&&out.patterns.size()==3&&out.activePattern==2,"selection Copy appends and selects exactly one pattern");
    expect(out.patterns[2].lanes[7]==std::vector<Note>({source.patterns[0].lanes[7][0],source.patterns[0].lanes[7][2]})&&out.patterns[0].lanes==source.patterns[0].lanes,"selection Copy retains source order, exact note articulation and every original lane");
    expect(out.patterns[2].length==8&&out.patterns[2].colour==8&&out.patterns[2].lanes[7][1].length==10&&out.patterns[2].editorId!=source.patterns[0].editorId,"extraction inherits colour/length, retains long gates and gives the result an independent identity");
    bool emptyOthers=true;for(int t=0;t<7;++t)emptyOthers&=out.patterns[2].lanes[(size_t)t].empty();expect(emptyOthers&&out.tracks.size()==source.tracks.size()&&JSON::toString(projectToJson(out)["clips"])==JSON::toString(projectToJson(source)["clips"]),"extraction creates no other notes, channels or Playlist instances");
    expect(stats.created==std::vector<int>{2}&&stats.extractedNotes==2&&stats.movedNotes==0&&stats.sourceTrack==7&&stats.shiftBeats==0,"copy statistics identify the exact new pattern and source lane");
    expect(render(source,assets,root,96000,127)==render(out,assets,root,96000,512),"Copy leaves actual Song audio sample-exact despite selecting the new pattern");
    expect(extractPatternNotes(source,0,7,{0,2},true,true,out,&stats).wasOk()&&out.patterns[0].lanes[7]==std::vector<Note>({source.patterns[0].lanes[7][1],source.patterns[0].lanes[7][3]}),"Move removes only the selected indices, retaining an unselected identical note");
    expect(out.patterns[2].lanes[7][0].beat==2.75&&out.patterns[2].lanes[7][1].beat==0&&out.patterns[2].lanes[7][1].length==10&&stats.shiftBeats==1.25&&stats.movedNotes==2,"alignment uses the earliest selected onset even for unsorted source notes and preserves gates");
    expect(out.patterns[0].lanes[0]==source.patterns[0].lanes[0]&&JSON::toString(projectToJson(out)["clips"])==JSON::toString(projectToJson(source)["clips"])&&out.markers[0].id=="phrase","Move preserves other channels, marker identities and all shared Playlist links");
    expect(JSON::toString(projectToJson(source))==original,"core extraction never mutates its const source");
    auto manual=out;manual.songMode=false;manual.patterns[2].lanes[7]={{2.75,1,60,.8f,.25f,3},{0,10,67,.7f,1,1}};auto audition=out;audition.songMode=false;expect(render(audition,assets,root,96000,127)==render(manual,assets,root,96000,511),"aligned extracted notes render like a manually authored phrase");
    auto file=root.getChildFile("extracted-selection.pulse");Project loaded;expect(saveProject(out,file).wasOk()&&loadProject(file,loaded).wasOk()&&JSON::toString(projectToJson(out))==JSON::toString(projectToJson(loaded)),"extracted and residual notes round-trip in unchanged project schema 14");
    auto sentinel=JSON::toString(projectToJson(out));stats.extractedNotes=99;auto rejectSelection=[&](const Project& p,int pat,int track,const std::set<int>& indices){return extractPatternNotes(p,pat,track,indices,true,true,out,&stats).failed()&&JSON::toString(projectToJson(out))==sentinel&&stats.extractedNotes==99;};
    for(const auto& indices:std::vector<std::set<int>>{{},{-1},{4},{0,99}})expect(rejectSelection(source,0,7,indices),"empty, negative and stale selections fail atomically without selecting all notes");
    expect(rejectSelection(source,-1,7,{0})&&rejectSelection(source,99,7,{0})&&rejectSelection(source,0,-1,{0})&&rejectSelection(source,0,8,{0}),"extraction rejects invalid pattern and channel indices atomically");
    auto bus=source;bus.tracks[7].isBus=true;expect(rejectSelection(bus,0,7,{0}),"extraction cannot create a note lane on a Mixer bus");
    auto full=source;while(full.patterns.size()<maxPatterns)full.patterns.push_back(incoming);expect(rejectSelection(full,0,7,{0}),"a full pattern bank never removes selected source notes");
    auto malformed=source;malformed.patterns[0].lanes.pop_back();expect(rejectSelection(malformed,0,7,{0}),"mismatched source lanes fail before extraction");
    auto alias=source;expect(extractPatternNotes(alias,0,7,{0,1,2,3},true,false,alias).wasOk()&&alias.patterns[0].lanes[7].empty()&&alias.patterns.back().lanes[7].size()==4,"in-place extraction supports moving the whole selected lane without dangling references");
    auto base=emptyProject();base.bpm=120;base.loop=false;base.patterns[0].colour=6;Note a{0,.5,60,.8f},b{1,1,64,.7f},b2{1,.25,64,.4f,.5f,2},c{0,.5,67,.6f},d{.1,.4,60,.6f};base.patterns[0].lanes[7]={a,b,a};Pattern right;right.name="Conflicts";right.length=4;right.lanes.resize(base.tracks.size());right.lanes[7]={a,b2,c,d};base.patterns.push_back(right);base.clips={{7,0,0,8},{7,1,8,4}};
    std::vector<std::vector<Note>> expected{{a,b,a,a,b2,c,d},{a,b,b2,c,d},{a,b,a,c,d},{a,b2,c,d}};
    for(int policy=0;policy<4;++policy){auto old=JSON::toString(projectToJson(base));expect(mergePatternLayers(base,0,1,out,&stats,(PatternMergePolicy)policy).wasOk()&&out.patterns.back().lanes[7]==expected[(size_t)policy],"each merge policy resolves exact duplicates or same-onset/pitch conflicts as specified");expect(stats.skippedNotes==7-(int)expected[(size_t)policy].size()&&out.patterns.back().colour==6&&out.patterns.back().length==8&&JSON::toString(projectToJson(base))==old,"merge statistics, length, colour and untouched sources agree with the policy");auto reference=out;reference.patterns.back().lanes[7]=expected[(size_t)policy];expect(render(out,assets,root,96000,127)==render(reference,assets,root,96000,511),"conflict-resolved merge audio matches the explicit reference across callback sizes");}
    auto acrossChannels=base;acrossChannels.patterns[1].lanes[6]={a};expect(mergePatternLayers(acrossChannels,0,1,out,nullptr,PatternMergePolicy::preferFirst).wasOk()&&out.patterns.back().lanes[6]==std::vector<Note>{a},"equal pitch and onset on another channel is never a merge conflict");
    auto dense=base;for(auto& p:dense.patterns)for(auto& lane:p.lanes)lane.clear();for(int i=0;i<512;++i)dense.patterns[0].lanes[7].push_back({i/64.,.01,60,.8f});dense.patterns[1].length=8;dense.patterns[1].lanes[7]=dense.patterns[0].lanes[7];
    for(auto policy:{PatternMergePolicy::skipExact,PatternMergePolicy::preferFirst,PatternMergePolicy::preferSecond})expect(mergePatternLayers(dense,0,1,out,&stats,policy).wasOk()&&out.patterns.back().lanes[7].size()==512&&stats.skippedNotes==512,"capacity is checked after conflict handling so two full matching lanes can merge");
    sentinel=JSON::toString(projectToJson(out));stats.skippedNotes=99;expect(mergePatternLayers(dense,0,1,out,&stats).failed()&&JSON::toString(projectToJson(out))==sentinel&&stats.skippedNotes==99,"keep-all still rejects 1024 notes without altering output or statistics");
    for(auto policy:{(PatternMergePolicy)-1,(PatternMergePolicy)4})expect(mergePatternLayers(base,0,1,out,&stats,policy).failed()&&JSON::toString(projectToJson(out))==sentinel,"invalid merge policy is rejected atomically");
    expect(mergePatternLayers(base,0,0,out,&stats,PatternMergePolicy::skipExact).failed()&&JSON::toString(projectToJson(out))==sentinel,"conflict options do not allow self-merging into an ambiguous copy");
    alias=base;expect(mergePatternLayers(alias,0,1,alias,nullptr,PatternMergePolicy::preferSecond).wasOk()&&alias.patterns.back().lanes[7]==expected[3],"in-place merge remains safe with filtering policies");
    auto batch=JSON::parse(R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[0,2],"alignStart":true},{"op":"merge_patterns","first":2,"second":1,"mode":"layered","policy":"skip_exact"},{"op":"set_pattern","pattern":3,"name":"Batch result"}])");
    expect(applyControlEdits(source,batch,out).wasOk()&&out.patterns.size()==4&&out.activePattern==3&&out.patterns[2].lanes[7][1].beat==0&&out.patterns[3].name=="Batch result"&&out.patterns[0].lanes==source.patterns[0].lanes,"atomic MCP batches can reference an extracted append in a later merge and rename");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[2,0],"move":true}])"),out).wasOk()&&out.patterns[0].lanes[7].size()==2&&out.patterns.back().lanes[7][0]==source.patterns[0].lanes[7][0],"MCP move uses source index order even when incoming index order differs");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"merge_patterns","first":0,"second":1,"mode":"sequential"}])"),out).wasOk()&&out.patterns.back().length==12&&out.patterns.back().lanes[7].back().beat==8,"MCP sequential merge retains full durations and defaults to keep-all");
    sentinel=JSON::toString(projectToJson(out));for(auto json:{R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[]}])",R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[0,0]}])",R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[true]}])",R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[4]}])",R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[0],"move":1}])",R"([{"op":"merge_patterns","first":0,"second":1,"policy":"bad"}])",R"([{"op":"merge_patterns","first":0,"second":1,"mode":"sequential","policy":"skip_exact"}])",R"([{"op":"merge_patterns","first":0,"second":1,"mode":true}])",R"([{"op":"extract_notes","pattern":0,"track":7,"indices":[0],"move":true},{"op":"set_pattern","pattern":99,"name":"bad"}])"})expect(applyControlEdits(source,JSON::parse(json),out).failed()&&JSON::toString(projectToJson(out))==sentinel,"invalid extraction/merge fields and later batch failures roll back every candidate edit");
}
